78	func newExplainCmd() *cobra.Command {
79		var sessionFlag string
80		var commitFlag string
81		var checkpointFlag string
82		var noPagerFlag bool
83		var shortFlag bool
84		var fullFlag bool
85		var rawTranscriptFlag bool
86		var generateFlag bool
87		var forceFlag bool
88		var searchAllFlag bool
89	
90		cmd := &cobra.Command{
91			Use:   "explain",
92			Short: "Explain a session, commit, or checkpoint",
93			Long: `Explain provides human-readable context about sessions, commits, and checkpoints.
94	
95	Use this command to understand what happened during agent-driven development,
96	either for self-review or to understand a teammate's work.
97	
98	By default, shows checkpoints on the current branch. Use flags to filter or
99	explain specific items.
100	
101	Filtering the list view:
102	  --session      Filter checkpoints by session ID (or prefix)
103	
104	Viewing specific items:
105	  --commit       Explain a specific commit (shows its associated checkpoint)
106	  --checkpoint   Explain a specific checkpoint by ID
107	
108	Output verbosity levels (for --checkpoint):
109	  Default:         Detailed view with scoped prompts (ID, session, tokens, intent, prompts, files)
110	  --short          Summary only (ID, session, timestamp, tokens, intent)
111	  --full           Parsed full transcript (all prompts/responses from entire session)
112	  --raw-transcript Raw transcript file (JSONL format)
113	
114	Summary generation (for --checkpoint):
115	  --generate    Generate an AI summary for the checkpoint
116	  --force       Regenerate even if a summary already exists (requires --generate)
117	
118	Performance options:
119	  --search-all  Remove branch/depth limits when searching for commits (may be slow)
120	
121	Checkpoint detail view shows:
122	  - Author of the checkpoint
123	  - Associated git commits that reference the checkpoint
124	  - Prompts and responses from the session
125	
126	Note: --session filters the list view; --commit and --checkpoint are mutually exclusive.`,
127			Args: func(_ *cobra.Command, args []string) error {
128				if len(args) > 0 {
129					return fmt.Errorf("unexpected argument %q\nHint: use --checkpoint, --session, or --commit to specify what to explain", args[0])
130				}
131				return nil
132			},
133			RunE: func(cmd *cobra.Command, _ []string) error {
134				// Check if Entire is disabled
135				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
136					return nil
137				}
138	
139				// Only initialize logging when inside a git worktree to avoid
140				// creating .entire/logs/ in arbitrary directories.
141				if _, err := paths.WorktreeRoot(cmd.Context()); err == nil {
142					logging.SetLogLevelGetter(GetLogLevel)
143					if err := logging.Init(cmd.Context(), ""); err == nil {
144						defer logging.Close()
145					}
146				}
147	
148				// Validate flag dependencies
149				if generateFlag && checkpointFlag == "" {
150					return errors.New("--generate requires --checkpoint/-c flag")
151				}
152				if forceFlag && !generateFlag {
153					return errors.New("--force requires --generate flag")
154				}
155				if rawTranscriptFlag && checkpointFlag == "" {
156					return errors.New("--raw-transcript requires --checkpoint/-c flag")
157				}
158	
159				// Convert short flag to verbose (verbose = !short)
160				verbose := !shortFlag
161				return runExplain(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionFlag, commitFlag, checkpointFlag, noPagerFlag, verbose, fullFlag, rawTranscriptFlag, generateFlag, forceFlag, searchAllFlag)
162			},
163		}
164	
165		cmd.Flags().StringVar(&sessionFlag, "session", "", "Filter checkpoints by session ID (or prefix)")
166		cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref, \"commit-ish\")")
167		cmd.Flags().StringVarP(&checkpointFlag, "checkpoint", "c", "", "Explain a specific checkpoint (ID or prefix)")
168		cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
169		cmd.Flags().BoolVarP(&shortFlag, "short", "s", false, "Show summary only (omit prompts and files)")
170		cmd.Flags().BoolVar(&fullFlag, "full", false, "Show full parsed transcript (all prompts/responses)")
171		cmd.Flags().BoolVar(&rawTranscriptFlag, "raw-transcript", false, "Show raw transcript file (JSONL format)")
172		cmd.Flags().BoolVar(&generateFlag, "generate", false, "Generate an AI summary for the checkpoint")
173		cmd.Flags().BoolVar(&forceFlag, "force", false, "Regenerate summary even if one already exists (requires --generate)")
174		cmd.Flags().BoolVar(&searchAllFlag, "search-all", false, "Search all commits (no branch/depth limit, may be slow)")
175	
176		// Make --short, --full, and --raw-transcript mutually exclusive
177		cmd.MarkFlagsMutuallyExclusive("short", "full", "raw-transcript")
178		// --generate and --raw-transcript are incompatible (summary would be generated but not shown)
179		cmd.MarkFlagsMutuallyExclusive("generate", "raw-transcript")
180	
181		return cmd
182	}
