184	// runExplain routes to the appropriate explain function based on flags.
185	func runExplain(ctx context.Context, w, errW io.Writer, sessionID, commitRef, checkpointID string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
186		// Count mutually exclusive flags (--commit and --checkpoint are mutually exclusive)
187		// --session is now a filter for the list view, not a separate mode
188		flagCount := 0
189		if commitRef != "" {
190			flagCount++
191		}
192		if checkpointID != "" {
193			flagCount++
194		}
195		// If --session is combined with --commit or --checkpoint, that's still an error
196		if sessionID != "" && flagCount > 0 {
197			return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
198		}
199		if flagCount > 1 {
200			return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
201		}
202	
203		// Route to appropriate handler
204		if commitRef != "" {
205			return runExplainCommit(ctx, w, commitRef, noPager, verbose, full, searchAll)
206		}
207		if checkpointID != "" {
208			return runExplainCheckpoint(ctx, w, errW, checkpointID, noPager, verbose, full, rawTranscript, generate, force, searchAll)
209		}
210	
211		// Default or with session filter: show list view (optionally filtered by session)
212		return runExplainBranchWithFilter(ctx, w, noPager, sessionID)
213	}
