215	// runExplainCheckpoint explains a specific checkpoint.
216	// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by git SHA).
217	// First tries to match committed checkpoints, then falls back to temporary checkpoints.
218	// When generate is true, generates an AI summary for the checkpoint.
219	// When force is true, regenerates even if a summary already exists.
220	// When rawTranscript is true, outputs only the raw transcript file (JSONL format).
221	// When searchAll is true, searches all commits without branch/depth limits (used for finding associated commits).
222	func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
223		repo, err := openRepository(ctx)
224		if err != nil {
225			return fmt.Errorf("not a git repository: %w", err)
226		}
227	
228		v1Store := checkpoint.NewGitStore(repo)
229		v2Store := checkpoint.NewV2GitStore(repo, strategy.ResolveCheckpointURL(ctx, "origin"))
230		preferCheckpointsV2 := settings.IsCheckpointsV2Enabled(ctx)
231	
232		// First, try to find in committed checkpoints by checkpoint ID prefix
233		committed, err := listCommittedForExplain(ctx, v1Store, v2Store, preferCheckpointsV2)
234		if err != nil {
235			return fmt.Errorf("failed to list checkpoints: %w", err)
236		}
237	
238		// Collect all matching checkpoint IDs to detect ambiguity
239		var matches []id.CheckpointID
240		for _, info := range committed {
241			if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
242				matches = append(matches, info.CheckpointID)
243			}
244		}
245	
246		// If not found locally, fetch metadata from remote and retry.
247		// This handles the case where we're looking at a checkpoint from another
248		// collaborator's PR whose metadata hasn't been fetched yet.
249		// Try origin first (fast treeless fetch, ~1-2s), then checkpoint_remote
250		// if configured and origin didn't have it. Fetch both v1 and v2 refs.
251		if len(matches) == 0 {
252			anyFetched := FetchMetadataTreeOnly(ctx) == nil
253			if !anyFetched {
254				anyFetched = FetchMetadataFromCheckpointRemote(ctx) == nil
255			}
256			if preferCheckpointsV2 {
257				v2Fetched := FetchV2MainTreeOnly(ctx) == nil
258				if !v2Fetched {
259					v2Fetched = FetchV2MetadataFromCheckpointRemote(ctx) == nil
260				}
261				anyFetched = anyFetched || v2Fetched
262			}
263			if anyFetched {
264				if freshRepo, repoErr := openRepository(ctx); repoErr == nil {
265					repo = freshRepo
266					v1Store = checkpoint.NewGitStore(repo)
267					v2Store = checkpoint.NewV2GitStore(repo, strategy.ResolveCheckpointURL(ctx, "origin"))
268					if freshCommitted, listErr := listCommittedForExplain(ctx, v1Store, v2Store, preferCheckpointsV2); listErr == nil {
269						for _, info := range freshCommitted {
270							if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
271								matches = append(matches, info.CheckpointID)
272							}
273						}
274					}
275				}
276			}
277		}
278	
279		var fullCheckpointID id.CheckpointID
280		switch len(matches) {
281		case 0:
282			// Not found in committed, try temporary checkpoints by git SHA
283			if generate {
284				return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
285			}
286			output, found := explainTemporaryCheckpoint(ctx, w, repo, v1Store, checkpointIDPrefix, verbose, full, rawTranscript)
287			if found {
288				outputExplainContent(w, output, noPager)
289				return nil
290			}
291			// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
292			if output != "" {
293				return errors.New(output)
294			}
295			return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
296		case 1:
