110	// TestFormatCheckpointSummaryError_TypedBranchesHandleEmptyMessage guards against
111	// the null-result-envelope regression: Claude can emit is_error:true with a real
112	// HTTP status (401/429/4xx) but result:null, producing a ClaudeError with Message="".
113	// The Auth/RateLimit/Config branches must not render a bare colon in that case.
114	func TestFormatCheckpointSummaryError_TypedBranchesHandleEmptyMessage(t *testing.T) {
115		t.Parallel()
116		kinds := []claudecode.ClaudeErrorKind{
117			claudecode.ClaudeErrorAuth,
118			claudecode.ClaudeErrorRateLimit,
119			claudecode.ClaudeErrorConfig,
120		}
121		for _, kind := range kinds {
122			t.Run(string(kind), func(t *testing.T) {
123				t.Parallel()
124				err := formatCheckpointSummaryError(&claudecode.ClaudeError{Kind: kind}, 0)
125				msg := err.Error()
126				// Must not end any line with a bare colon (the classic regression
127				// of rendering "...: " with nothing after it).
128				for _, line := range strings.Split(msg, "\n") {
129					if strings.HasSuffix(strings.TrimSpace(line), ":") {
130						t.Errorf("line ends with bare colon: %q (full: %q)", line, msg)
131					}
132				}
133			})
134		}
135	}
