174	// TestFormatCheckpointSummaryError_Unknown covers the three branches of the
175	// default-case suffix builder. Guards against users seeing
176	// "Claude failed to generate the summary:" with nothing after the colon
177	// (the null-result and no-stderr-OOM scenarios).
178	func TestFormatCheckpointSummaryError_Unknown(t *testing.T) {
179		t.Parallel()
180		tests := []struct {
181			name string
182			err  *claudecode.ClaudeError
183			want string // substring that must appear in the rendered message
184		}{
185			{"APIStatus when Message empty", &claudecode.ClaudeError{Kind: claudecode.ClaudeErrorUnknown, APIStatus: 500}, "500"},
186			{"ExitCode when Message empty", &claudecode.ClaudeError{Kind: claudecode.ClaudeErrorUnknown, ExitCode: 137}, "137"},
187			{"Negative ExitCode renders as abnormal, not -1", &claudecode.ClaudeError{Kind: claudecode.ClaudeErrorUnknown, ExitCode: -1}, "abnormal"},
188			{"All-zero fields render a diagnostic sentinel, not empty", &claudecode.ClaudeError{Kind: claudecode.ClaudeErrorUnknown}, "no diagnostic detail"},
189			{"Message takes precedence", &claudecode.ClaudeError{Kind: claudecode.ClaudeErrorUnknown, Message: "something weird"}, "something weird"},
190		}
191		for _, tc := range tests {
192			t.Run(tc.name, func(t *testing.T) {
193				t.Parallel()
194				msg := formatCheckpointSummaryError(tc.err, 0).Error()
195				if strings.HasSuffix(strings.TrimSpace(msg), ":") {
196					t.Errorf("user-facing message ends with bare colon: %q", msg)
197				}
198				if !strings.Contains(msg, tc.want) {
199					t.Errorf("missing %q in %q", tc.want, msg)
200				}
201			})
202		}
203	}
